        { "q": "프랑스 리옹의 미셸 느와르 시장은 야간 경관을 위해 무엇을 했나요?", "a": "공약에 따라 5년 동안 해마다 시 재정의 5퍼센트씩을 투입하여 도시의 건물과 교량 150곳에 조명 기기를 설치했다." },
        { "q": "그 결과 리옹의 밤은 어떻게 바뀌었나요?", "a": "밤이 되면 도시 전체가 하나의 커다란 조명 예술 작품처럼 보이는 곳으로 바뀌어, 건축물과 공간의 아름다움을 새롭게 보여 주었다." }
