        { "q": "포그가 연료가 떨어지자 배를 통째로 사들인 행동은 그가 무엇을 가장 중요하게 여겼음을 보여 주나요?", "a": "5만 달러짜리 배를 6만 달러에 사서 나무 부분을 연료로 쓰며 항해를 계속한 것으로 보아, 포그에게 가장 중요한 것은 80일 안에 세계 일주를 마치는 일이었음을 보여 준다." }
