        { "q": "순자가 인간의 본성이 악하다고 한 말의 진정한 의미는 무엇인가요?", "a": "인간이 태어날 때부터 나쁜 행동만 한다는 뜻이 아니라, 생리적 욕구에 바탕을 둔 이기심이 모두에게 있어 각자 욕구대로만 행동하면 서로 다투는 다툼과 혼란이 일어날 수 있다는 의미이다." }
